  252:     /// A clean write of `files_written` file(s) carrying `bytes_written`
  253:     /// bytes. Write sites construct through this rather than a struct
  254:     /// literal so later fields do not ripple through every one of them.
  255:     pub fn written(files_written: usize, bytes_written: u64) -> Self {
  256:         Self {
  257:             files_written,
  258:             bytes_written,
  259:             failures: Vec::new(),
  260:             files_failed_total: 0,
  261:             failed_paths: std::collections::HashSet::new(),
  262:             left_in_place: std::collections::HashSet::new(),
  263:         }
  264:     }
