  266:     /// One file that could not be written. Nothing is counted as landed
  267:     /// for it — a failed file is never a written file, whatever partial
  268:     /// bytes reached the destination.
  269:     pub fn failed(relative_path: impl Into<String>, reason: impl Into<String>) -> Self {
  270:         let mut outcome = Self::default();
  271:         outcome.record_failure(relative_path, reason);
  272:         outcome
  273:     }
