  275:     /// Record one per-file failure. The reported list stops growing at
  276:     /// [`MAX_REPORTED_FILE_FAILURES`]; the total keeps counting.
  277:     pub fn record_failure(&mut self, relative_path: impl Into<String>, reason: impl Into<String>) {
  278:         let relative_path = relative_path.into();
  279:         let reason = reason.into();
  280:         // Every contained failure is logged here, exactly once — the one
  281:         // point every recorded failure passes through. A contained file
  282:         // that logs nothing is indistinguishable from a transferred one,
  283:         // and the log is the only surface a failure has until the summary
  284:         // carries the report. `merge`/`merge_failures` copy records rather
  285:         // than re-recording them, so no file is logged twice.
  286:         let named = if relative_path.is_empty() {
  287:             "<destination root>"
  288:         } else {
  289:             relative_path.as_str()
  290:         };
  291:         log::warn!("file failed, session continues: {named} ({reason})");
  292:         self.files_failed_total = self.files_failed_total.saturating_add(1);
  293:         self.failed_paths.insert(relative_path.clone());
  294:         if reason.contains(INCOMPLETE_LEFT_IN_PLACE) {
  295:             self.left_in_place.insert(relative_path.clone());
  296:         }
  297:         if self.failures.len() < MAX_REPORTED_FILE_FAILURES {
  298:             self.failures.push(FileFailure {
  299:                 relative_path,
  300:                 reason,
  301:             });
  302:         }
  303:     }
