  350:     ///
  351:     /// Per-payload identity (`failed_paths`) IS folded in (cr-ssc1-1,
  352:     /// SOURCE_SIDE_CONTAINMENT A19): the mirror pass needs the exact,
  353:     /// uncapped set of failed paths to shield their destination subtrees
  354:     /// from deletion, and an exact set also lets
  355:     /// [`SinkOutcome::file_failed`] answer per path on a merged outcome.
  356:     /// Only the wire report (`failures`) stays bounded.
  357:     pub fn merge_failures(&mut self, other: &SinkOutcome) {
  358:         self.files_failed_total = self
  359:             .files_failed_total
  360:             .saturating_add(other.files_failed_total);
  361:         let room = MAX_REPORTED_FILE_FAILURES.saturating_sub(self.failures.len());
  362:         self.failures
  363:             .extend(other.failures.iter().take(room).cloned());
  364:         self.failed_paths.extend(other.failed_paths.iter().cloned());
  365:         self.left_in_place
  366:             .extend(other.left_in_place.iter().cloned());
  367:     }
